process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const TOK=process.env.GH_TOKEN||''; const REPO=process.env.GH_REPO||'raimis079-creator/petshop-bridge';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from(process.env.WP_USER+':'+process.env.WP_APP_PASS).toString('base64');
const D64=''; const A64='';
const out={versija:'P1O'};
async function put(name,buf,msg){
  let sha=null;
  try{const g=await fetch(`https://api.github.com/repos/${REPO}/contents/screenshots/${name}`,{headers:{'Authorization':'Bearer '+TOK,'User-Agent':'b'}});if(g.status===200)sha=(await g.json()).sha;}catch(e){}
  const b={message:msg,content:buf.toString('base64')}; if(sha) b.sha=sha;
  await fetch(`https://api.github.com/repos/${REPO}/contents/screenshots/${name}`,{method:'PUT',headers:{'Authorization':'Bearer '+TOK,'Content-Type':'application/json','User-Agent':'b'},body:JSON.stringify(b)});
}
async function api(p,o={}){ const r=await fetch(WP+p,{...o,headers:{Authorization:AUTH,'Content-Type':'application/json',...(o.headers||{})}}); return {s:r.status,t:await r.text()}; }
async function snip(n,b64){ const code=Buffer.from(b64,'base64').toString('utf8'); const cr=await api('/wp-json/code-snippets/v1/snippets',{method:'POST',body:JSON.stringify({name:n,code,scope:'global',active:true,priority:5})}); let j=null; try{j=JSON.parse(cr.t);}catch(e){} return j?j.id:null; }
async function off(id){ if(id) await api('/wp-json/code-snippets/v1/snippets/'+id,{method:'POST',body:JSON.stringify({id,active:false})}); }
try{
  const sD=await snip('TEMP P1O DEPLOYH',D64);
  await new Promise(r=>setTimeout(r,5500));
  out.deploy=JSON.parse(await (await fetch(WP+'/?ps_p0=DEPH')).text());
  await off(sD);
  const sA=await snip('TEMP P1O E2EA',A64);
  await new Promise(r=>setTimeout(r,5000));
  const prep=JSON.parse(await (await fetch(WP+'/?ps_p0=E2EA')).text());
  await off(sA);
  const { chromium } = await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true,viewport:{width:1500,height:1100}});
  const ck=[{name:prep.cookie_name,value:prep.cookie_value,domain:'dev.avesa.lt',path:'/'}];
  if(prep.sec_name) ck.push({name:prep.sec_name,value:prep.sec_value,domain:'dev.avesa.lt',path:'/'});
  if(prep.auth_name) ck.push({name:prep.auth_name,value:prep.auth_value,domain:'dev.avesa.lt',path:'/wp-admin'});
  await ctx.addCookies(ck);
  const p=await ctx.newPage();
  out.js=[]; p.on('pageerror',e=>out.js.push(String(e).slice(0,140)));
  const B=WP+'/wp-admin/admin.php?page=petshop-reports-anketa&preset=visi&skiltis=';
  for(const s of ['paklausa','pinigai']){
    await p.goto(B+s,{waitUntil:'domcontentloaded',timeout:45000});
    await new Promise(r=>setTimeout(r,1200));
    out[s]={
      h3:await p.evaluate(()=>[...document.querySelectorAll('.psru-h3')].map(x=>x.textContent.trim())),
      lent:await p.evaluate(()=>[...document.querySelectorAll('table.psru-lent')].map(t=>({id:t.id,eil:t.tBodies[0].rows.length}))),
      kpi:await p.evaluate(()=>[...document.querySelectorAll('.psru-k h3')].map(x=>x.textContent.replace(/\s+/g,' ').trim())),
    };
    await put('v22_'+s+'.png', await p.screenshot({fullPage:true}), 'v2.2 '+s);
  }
  await br.close();
}catch(e){ out.bendra=String(e).slice(0,300); }
await put('p1o.json', Buffer.from(JSON.stringify(out)), 'p1o v2.2');
console.log('ok');
